package dev.homecontrol.app;

import android.app.*;
import android.os.Bundle;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Native food/mode browser; all network calls use HomeControl's own account session. */
public final class RecipesActivity extends AppPage {
    private String id,tab,container="",query="",focus="";private int page=1;private volatile int generation;private boolean destroyed,writing;
    private AlertDialog sendingDialog;private final Map<String,TextView> tabButtons=new LinkedHashMap<>();private EditText search;private TextView status;private LinearLayout results;private final ExecutorService worker=Executors.newSingleThreadExecutor();
    interface Job{Object run()throws Exception;}interface Done{void accept(Object value)throws Exception;}
    @Override public void onCreate(Bundle state){super.onCreate(state);id=getIntent().getStringExtra("id");if(id==null||!id.startsWith("mijia:")){finish();return;}tab=getIntent().getStringExtra("tab");if(tab==null)tab="modes";focus=getIntent().getStringExtra("focusMode");if(focus==null)focus="";if(state!=null)focus="";
        if(state!=null){tab=state.getString("tab",tab);query=state.getString("query","");container=state.getString("container","");}page("设备菜单与食谱",this::finish);
        search=new EditText(this);search.setSingleLine(true);search.setHint("搜索食谱");search.setText(query);search.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);search.setSaveEnabled(false);content.addView(search,new LinearLayout.LayoutParams(-1,ui.dp(52)));ui.space(content,10);
        LinearLayout tabs=ui.row();String[] names={"设备模式","发现","收藏","搜索"};String[] values={"modes","discover","favorites","search"};for(int i=0;i<names.length;i++){final String t=values[i];TextView b=button(names[i],()->{if(writing)return;tab=t;container="";query=search.getText().toString().trim();page=1;load(false);});tabButtons.put(t,b);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,ui.dp(44),1);p.rightMargin=ui.dp(5);tabs.addView(b,p);}content.addView(tabs);ui.space(content,12);
        status=ui.text("正在读取…",13,ui.muted,false);status.setMinHeight(ui.dp(34));content.addView(status);results=ui.column();content.addView(results);search.setOnEditorActionListener((v,a,e)->{if(a==android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH&&!writing){tab="search";container="";query=search.getText().toString().trim();page=1;load(false);return true;}return false;});load(false);
    }
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putString("tab",tab);state.putString("query",query);state.putString("container",container);}
    @Override protected void onDestroy(){destroyed=true;generation++;worker.shutdown();super.onDestroy();}
    private TextView button(String label,Runnable click){TextView b=ui.text(label,14,ui.accent,true);b.setPadding(ui.dp(8),ui.dp(10),ui.dp(8),ui.dp(10));b.setGravity(Gravity.CENTER);b.setBackground(ui.ripple(ui.surface,15));b.setOnClickListener(v->click.run());return b;}
    private void request(Job job,Done done){final int n=++generation;status.setText(writing?"正在提交，请勿重复操作…":"正在读取…");final boolean wasWrite=writing;worker.execute(()->{if(n!=generation&&!wasWrite)return;Object value=null;String error=null;try{value=job.run();}catch(Exception e){error=wasWrite?CloudDevices.error(e,"操作结果未确认")+"；不会重复发送，请刷新确认":CloudDevices.error(e,"读取失败，请稍后重试");}final Object out=value;final String failure=error;runOnUiThread(()->{if(destroyed||n!=generation)return;try{if(failure!=null){failed(failure);return;}done.accept(out);}catch(Exception e){failed(CloudDevices.error(e,"数据格式暂不支持"));}});});}
    private void failed(String message){writing=false;if(sendingDialog!=null){sendingDialog.dismiss();sendingDialog=null;}status.setText(message);}
    private void load(boolean append){if(writing)return;for(Map.Entry<String,TextView> t:tabButtons.entrySet())t.getValue().setBackground(ui.ripple(tab.equals(t.getKey())?ui.pale:ui.surface,15));String op="modes".equals(tab)?(container.isEmpty()?"recipes.home":"recipes.optional"):"favorites".equals(tab)?"recipes.favorites":"search".equals(tab)?"recipes.search":"recipes.recommended";
        if("search".equals(tab)&&query.isEmpty()){status.setText("请输入食谱名称");results.removeAllViews();return;}
        try{JSONObject args=new JSONObject().put("query",query).put("page",page);if(!container.isEmpty())args.put("containerId",container);String section=tab;request(()->MijiaCloud.feature(this,id,op,args),raw->{JSONArray items=FeatureData.items(raw,section);if(!append)results.removeAllViews();status.setText(items.length()==0?"当前栏目暂无内容":"modes".equals(section)?"设备提供的菜单":"食谱来自设备服务");for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);boolean isContainer=item.optBoolean("isContainer")||item.optBoolean("isSelfChooseMode")||item.optBoolean("isSelfChoose");String title=item.getString("_title");String source="modes".equals(section)?(container.isEmpty()?"home":"optional"):"detail";String parent=container;
                if(!focus.isEmpty()&&focus.equals(title)){focus="";results.post(()->{if(destroyed)return;if(isContainer){container=item.optString("bussinessId",item.optString("_id"));page=1;load(false);}else open(item,source,parent);});}
                View row=option(title,isContainer?"展开选择":"modes".equals(section)?"设置烹饪参数":"查看食材、步骤与烹饪设置",AppUi.DEVICES,()->{if(writing)return;if(isContainer){container=item.optString("bussinessId",item.optString("_id"));tab="modes";page=1;load(false);}else open(item,source,parent);});results.addView(row);ui.space(results,8);}
            if(items.length()>=10&&("search".equals(section)||"discover".equals(section))){TextView more=button("下一页",()->{page++;load(false);});results.addView(more);}if(!container.isEmpty())results.addView(button("返回设备模式",()->{container="";page=1;load(false);}));
        });}catch(Exception e){status.setText("读取参数无效");}
    }
    private JSONObject selection(JSONObject item,String source,String parent)throws Exception{JSONObject in=new JSONObject().put("recipeId",item.getString("_id")).put("menuType",item.optString("_menuType","1")).put("source",source);if(!parent.isEmpty())in.put("containerId",parent);return in;}
    private void open(JSONObject item,String source,String parent){try{JSONObject in=selection(item,source,parent);if(!"detail".equals(source)){prepare(in);return;}request(()->MijiaCloud.feature(this,id,"recipes.detail",in),raw->{JSONObject detail=FeatureData.object(raw);status.setText("食谱已读取");LinearLayout view=ui.column();view.setPadding(ui.dp(22),ui.dp(8),ui.dp(22),ui.dp(18));TextView text=ui.text(FeatureData.detailText(detail),15,ui.text,false);text.setLineSpacing(ui.dp(4),1);view.addView(text);ScrollView sc=new ScrollView(this);sc.addView(view);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(item.optString("_title")).setView(sc).setPositiveButton("烹饪设置",(d,w)->prepare(in)).setNegativeButton("返回",null).setNeutralButton(detail.optBoolean("isCollect")?"取消收藏":"收藏",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setOnClickListener(w->{if(writing)return;writing=true;sendingDialog=dialog;dialog.getButton(AlertDialog.BUTTON_NEUTRAL).setEnabled(false);try{JSONObject favorite=new JSONObject(in.toString()).put("add",!detail.optBoolean("isCollect"));request(()->MijiaCloud.feature(this,id,"recipes.favorite",favorite),out->{FeatureData.unwrap(out);writing=false;status.setText("收藏已更新");dialog.dismiss();});}catch(Exception e){writing=false;status.setText("收藏参数无效");}}));dialog.show();});}catch(Exception e){status.setText("食谱参数无效");}}
    private void prepare(JSONObject in){request(()->MijiaCloud.feature(this,id,"kitchen.prepare",in),raw->{JSONObject draft=(JSONObject)raw;status.setText("请选择参数；确认后才会启动设备");LinearLayout form=ui.column();form.setPadding(ui.dp(22),ui.dp(8),ui.dp(22),ui.dp(16));Map<String,EditText> fields=new LinkedHashMap<>();
            form.addView(ui.text("时长单位："+draft.optString("unit"),14,ui.muted,false));if(draft.optBoolean("timeEditable")){addNumber(form,fields,"time","时长（"+draft.optInt("minTime")+"～"+draft.optInt("maxTime")+" "+draft.optString("unit")+"）",draft.optInt("time"));}else form.addView(ui.text(draft.optBoolean("weightEditable")?"时长按份量自动调整":"时长："+draft.optInt("time")+" "+draft.optString("unit"),16,ui.text,true));
            Spinner fire=new Spinner(this);if(draft.optBoolean("fireEditable")){form.addView(ui.text("火力",14,ui.text,true));fire.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"高火","中高火","中火","中低火","低火"}));fire.setSelection(Math.min(4,Math.max(0,draft.optInt("fire"))));form.addView(fire);}Spinner weight=new Spinner(this);JSONArray weightOptions=draft.optJSONArray("weightOptions");if(draft.optBoolean("weightEditable")&&weightOptions!=null&&weightOptions.length()>0){form.addView(ui.text("份量与预计时长",14,ui.text,true));List<String> labels=new ArrayList<>();int chosen=0;for(int wi=0;wi<weightOptions.length();wi++){JSONObject value=weightOptions.getJSONObject(wi);labels.add(value.getInt("weight")+" "+draft.optString("weightUnit","g")+" · "+value.getInt("time")+" 秒");if(value.getInt("weight")==draft.optInt("weight"))chosen=wi;}weight.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels));weight.setSelection(chosen);form.addView(weight);}
            ui.space(form,12);form.addView(ui.text("秒".equals(draft.optString("unit"))?"请确认已放好食材并关好炉门，使用微波炉适用的容器。":"请确认已放好食材并合上锅盖。",13,ui.muted,false));ScrollView sc=new ScrollView(this);sc.addView(form);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(draft.optString("name","烹饪设置")).setView(sc).setPositiveButton("确认启动",null).setNegativeButton("取消",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{if(writing)return;try{JSONObject args=new JSONObject(in.toString());for(Map.Entry<String,EditText> f:fields.entrySet())args.put(f.getKey(),Integer.parseInt(f.getValue().getText().toString().trim()));if(draft.optBoolean("fireEditable"))args.put("fire",fire.getSelectedItemPosition());if(draft.optBoolean("weightEditable")&&weightOptions!=null&&weightOptions.length()>0)args.put("weight",weightOptions.getJSONObject(weight.getSelectedItemPosition()).getInt("weight"));for(String key:fields.keySet()){int min=draft.optInt("weight".equals(key)?"minWeight":"minTime"),max=draft.optInt("weight".equals(key)?"maxWeight":"maxTime");if(args.getInt(key)<min||args.getInt(key)>max)throw new IllegalArgumentException("参数超出菜单范围");}
                    writing=true;sendingDialog=dialog;dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(false);dialog.setCancelable(false);dialog.getButton(AlertDialog.BUTTON_NEGATIVE).setEnabled(false);request(()->MijiaCloud.feature(this,id,"kitchen.start",args),out->{writing=false;status.setText(((JSONObject)out).optString("message","请刷新设备状态"));dialog.dismiss();});
                }catch(Exception e){Toast.makeText(this,e.getMessage()==null?"请填写有效参数":e.getMessage(),Toast.LENGTH_LONG).show();}}));dialog.show();});}
    private void addNumber(LinearLayout form,Map<String,EditText> fields,String key,String title,int value){ui.space(form,10);form.addView(ui.text(title,14,ui.text,true));EditText edit=new EditText(this);edit.setSingleLine(true);edit.setInputType(InputType.TYPE_CLASS_NUMBER);edit.setSaveEnabled(false);edit.setText(Integer.toString(value));form.addView(edit);fields.put(key,edit);}
}
